    public Task<WorkflowReviewContext> ReviewContext(Guid root,Guid card,int revision,ClaimsPrincipal actor,CancellationToken ct)=>Snapshot(actor,null,async(_,manage)=>{
        if(!manage)throw new OrganizationForbidden();var source=await Live().SingleOrDefaultAsync(c=>c.RootId==root&&c.CardId==card,ct)??throw new OrganizationNotFound();var review=await db.Reviews.AsNoTracking().SingleAsync(r=>r.Id==root,ct);if(review.Revision!=revision)throw new OrganizationConflict("The received review changed. Refresh the review workspace before authorizing an exception.");return new WorkflowReviewContext(source.ProgramId,source.CampaignId,source.OpportunityId,source.PublicationRevision,source.PublicationSha256,root,card,review.Revision,review.HeadSha256);
    },ct);
    public Task<WorkflowExceptionEvidence> PreviewException(Guid program,WorkflowExceptionPreviewRequest request,ClaimsPrincipal actor,CancellationToken ct)=>Snapshot(actor,null,async(_,manage)=>{
        if(!manage)throw new OrganizationForbidden();var card=await Card(request.OpportunityId,request.PublicationRevision,ct);if(card.ProgramId!=program)throw new OrganizationNotFound();var command=new WorkflowExceptionCommand(1,Guid.Empty,0,card.Id,card.Revision,Hash(card),WorkflowExceptionKind.ApprovedWithExceptions,"preview","preview","preview",request.RequirementKey,RootReceiptId:request.RootReceiptId,LocalCardId:request.LocalCardId,Evidence:request.Evidence,ExpectedReviewRevision:request.ExpectedReviewRevision,ExpectedReviewHeadSha256:request.ExpectedReviewHeadSha256);var source=await Source(card,command,ct);return new WorkflowExceptionEvidence(new(program,card.CampaignId,card.Id,card.Revision,Hash(card),request.RootReceiptId,request.LocalCardId,source.Revision,source.Head),source.Outcomes,source.HasOriginals,source.EvidenceSha256,source.Signature);
    },ct);
    async Task<WorkflowExceptionSnapshot> Exception(WorkflowExceptionRecord row,CancellationToken ct)
    {var s=await Original<WorkflowExceptionSnapshot>(row.Id,row.Revision,"workflow-exception",row.SnapshotSha256,ct);if(s.Id!=row.Id||s.ProgramId!=row.ProgramId||s.Active!=row.Active||s.ScopeSha256!=row.ScopeSha256||s.RulesRevision!=row.RulesRevision)throw new InvalidOperationException("Exception index differs from its immutable decision.");return s;}
    async Task SaveException(WorkflowExceptionRecord row,WorkflowExceptionSnapshot value,CancellationToken ct)
    {
        var d=value.Definition;row.Revision=value.Revision;row.ProgramId=value.ProgramId;row.CampaignId=value.CampaignId;row.OpportunityId=d.OpportunityId;row.PublicationRevision=d.PublicationRevision;row.PublicationSha256=d.PublicationSha256;row.RequirementKey=d.RequirementKey??"";row.PhaseId=d.PhaseId;row.PhaseDefinitionRevision=value.PhaseDefinitionRevision;row.RulesRevision=value.RulesRevision;row.Kind=d.Kind;row.Active=value.Active;row.CountAsPartialContributor=d.CountAsPartialContributor;row.RootReceiptId=d.RootReceiptId;row.CardId=d.LocalCardId;row.PilotId=value.PilotId;row.ClaimId=value.ClaimId;row.SourceSignature=value.SourceSignature;row.SourceState=value.SourceState;row.SourceReviewRevision=value.SourceReviewRevision;row.SourceReviewHeadSha256=value.SourceReviewHeadSha256;row.ScopeSha256=value.ScopeSha256;row.TimestampUtc=value.TimestampUtc;row.SnapshotJson=JsonSerializer.Serialize(value,WireJson.Options);row.SnapshotSha256=Hash(value);history.Revision(row.Id,row.Revision,"workflow-exception",value,value.ActorId);history.Audit(value.ActorId,value.Actor,"exception-"+value.Action,row.Id,row.Revision);await db.SaveChangesAsync(ct);
    }
    sealed record ExceptionSource(Guid PilotId,Guid ClaimId,int Revision,string Head,string Signature,ResearchReviewState State,ApprovedOutcomeCount[] Outcomes,string EvidenceSha256,bool HasOriginals);
    async Task<ExceptionSource> Source(OrganizationOpportunitySnapshot published,WorkflowExceptionCommand command,CancellationToken ct)
    {
        if(command.RootReceiptId is not {} root||command.LocalCardId is not {} card||command.ExpectedReviewRevision is null||command.ExpectedReviewHeadSha256 is null)throw new ArgumentException("Choose the actual received submission/card and its current review revision/head. A draft or local result is not a received contribution.");
        var review=await db.Reviews.AsNoTracking().SingleOrDefaultAsync(r=>r.Id==root&&r.ProgramId==published.ProgramId&&r.CampaignId==published.CampaignId,ct)??throw new OrganizationNotFound();if(review.Revision!=command.ExpectedReviewRevision||review.HeadSha256!=command.ExpectedReviewHeadSha256)throw new OrganizationConflict("This received review changed. Reopen the current evidence before authorizing an exception.");
        var contribution=await Live().SingleOrDefaultAsync(c=>c.RootId==root&&c.CardId==card&&c.OpportunityId==published.Id&&c.PublicationRevision==published.Revision&&c.PublicationSha256==command.PublicationSha256,ct)??throw new OrganizationConflict("This submission has no current verifiable binding to the exact issued card. Restore/verify its original evidence first.");
        var original=await OrganizationReviews.ReadDocument(db,root,ct);SubmissionEvidenceProtocol.Validate(original,ct);var binding=original.Manifest.Cards.SingleOrDefault(c=>c.CardId==card&&c.OpportunityId==published.Id&&c.IssuedRevision==published.Revision&&c.IssuedSha256==command.PublicationSha256)??throw new OrganizationNotFound();var claim=await db.Claims.AsNoTracking().SingleAsync(c=>c.Id==binding.ClaimId,ct);
        if(original.Manifest.PilotId!=claim.UserId||contribution.PilotId!=claim.UserId||contribution.ClaimId!=claim.Id||claim.IssuedSha256!=binding.IssuedSha256||claim.IssuedRevision!=binding.IssuedRevision)throw new OrganizationForbidden();
        var definition=original.Evidence.Single(i=>i.Reference.CardId==card&&i.Data.Definition!=null).Data.Definition!;if(!MissionStore.MatchesSubmissionDefinition(definition,published)||Hash(definition)!=binding.DefinitionSha256)throw new OrganizationConflict("The submitted definition differs from the issued publication.");
        var docs=await OrganizationReviews.Selected(db,review,command.Evidence??[],card,ct);foreach(var doc in docs)SubmissionEvidenceProtocol.Validate(doc,ct);var items=docs.SelectMany(d=>d.Evidence).Where(i=>i.Reference.CardId==card).ToArray();var results=items.Select(i=>i.Data.Result).OfType<PersonalResearchAttempt>().DistinctBy(r=>r.Id).ToArray();var point=command.RequirementKey is {} key?Requirements(published).Single(q=>q.Key==key).PointId:null;
        var pointAttempts=point is {} pid?items.SelectMany(i=>i.Data.Telemetry?.Attempts??[]).Where(a=>a.TestPointId==pid&&a.PointEvidence!=null).DistinctBy(a=>a.Id).Select(a=>a.PointEvidence!.Outcome).ToArray():[];
        var outcomes=point is {} pointId?pointAttempts.Length>0?pointAttempts:results.SelectMany(r=>(r.Procedure?.Points.Where(p=>p.PointId==pointId).Select(p=>p.Outcome)??[]).Concat(r.QuantitativePoint?.PointId==pointId?[r.QuantitativePoint.Outcome]:[])).ToArray():results.Select(r=>r.Outcome).ToArray();
        var summary=outcomes.GroupBy(x=>x).Select(g=>new ApprovedOutcomeCount(g.Key,g.LongCount(),"Original received client outcome — never rewritten by this organizational disposition")).ToArray();var receipts=command.Evidence!.Select(e=>e.ReceiptId).Distinct().ToArray();var hashes=await db.Submissions.AsNoTracking().Where(s=>receipts.Contains(s.ReceiptId)).OrderBy(s=>s.ReceiptId).Select(s=>new{s.ReceiptId,s.ManifestSha256,s.PayloadSha256}).ToArrayAsync(ct);var hash=Hash(new{references=command.Evidence,receipts=hashes});var has=items.Any(i=>i.Data.Telemetry?.Samples.Length>0||i.Data.Observations?.Length>0||i.Data.Documentation?.Length>0);
        return new(claim.UserId,claim.Id,review.Revision,review.HeadSha256,contribution.ApprovalSignature,contribution.State,summary,hash,has);
    }
    public async Task<WorkflowExceptionSnapshot> AuthorizeException(Guid program,WorkflowExceptionCommand command,ClaimsPrincipal actor,CancellationToken ct)
    {
        if(command.Version!=1||command.RequestId==Guid.Empty||command.ExpectedPolicyRevision<1||!Enum.IsDefined(command.Kind)||!command.Confirm||command.OpportunityId==Guid.Empty||command.PublicationRevision<1||!CampaignCoverageRules.Hash(command.PublicationSha256)||command.RequirementKey?.Length>100||command.RequirementKey is not null&&string.IsNullOrWhiteSpace(command.RequirementKey)||command.Kind==WorkflowExceptionKind.RequirementWaiver&&command.CountAsPartialContributor)throw new ArgumentException("Choose an exact published card/requirement, current policy and deliberately confirm the administrative disposition. A waiver never counts as a pilot.");
        ProgramWorkflowRules.Text(command.Reason,2000,"Reason");ProgramWorkflowRules.Text(command.Justification,2000,"Justification");ProgramWorkflowRules.Text(command.UnmetCriteria,2000,"Original unmet/limited criteria");
        return await history.Mutate(actor,command.RequestId,new{operation="authorize-workflow-exception",program,command},async(id,name)=>{
            var policy=await Policy(program,ct);if(policy.Revision!=command.ExpectedPolicyRevision)throw new OrganizationConflict("The authorization policy changed. Review its current rules before authorizing this exception.");var published=await Card(command.OpportunityId,command.PublicationRevision,ct);if(published.ProgramId!=program||Hash(published)!=command.PublicationSha256||command.RequirementKey is {} key&&!Requirements(published).Any(q=>q.Key==key))throw new ArgumentException("The exception must bind this program's exact published card and requirement identity.");
            TestPhaseSnapshot? phase=null;bool waivers=policy.Policy.AllowCampaignWaivers,exceptions=policy.Policy.AllowCampaignExceptions,partial=policy.Policy.CountAuthorizedPartialContributors;
            if(command.PhaseId is {} phaseId){var row=await db.TestPhases.AsNoTracking().SingleOrDefaultAsync(p=>p.Id==phaseId&&p.ProgramId==program&&p.Enabled,ct)??throw new OrganizationNotFound();phase=await Phase(row,ct);if(command.ExpectedPhaseDefinitionRevision!=phase.DefinitionRevision)throw new OrganizationConflict("The phase definition changed. Reopen its exact current requirements.");var rule=phase.Definition.Requirements.SingleOrDefault(r=>r.OpportunityId==published.Id&&r.PublicationRevision==published.Revision&&r.PublicationSha256==command.PublicationSha256&&r.RequirementKey==command.RequirementKey)??throw new OrganizationConflict("This disposition is not scoped to an exact requirement in this phase. It cannot spread to another card, point or publication.");waivers=rule.AllowWaivers;exceptions=rule.AllowExceptions;partial=rule.CountAuthorizedPartialContributors;}
            else if(command.ExpectedPhaseDefinitionRevision is not null)throw new ArgumentException("A campaign disposition has no phase revision.");
            if(command.Kind==WorkflowExceptionKind.RequirementWaiver&&!waivers||command.Kind==WorkflowExceptionKind.ApprovedWithExceptions&&!exceptions||command.CountAsPartialContributor&&!partial)throw new OrganizationConflict("The current policy does not permit this disposition or partial-contributor credit for the stated purpose.");
            ExceptionSource? source=null;if(command.RootReceiptId is not null||command.Kind==WorkflowExceptionKind.ApprovedWithExceptions)source=await Source(published,command,ct);else if(command.LocalCardId is not null||command.Evidence?.Length>0||command.ExpectedReviewRevision is not null||command.ExpectedReviewHeadSha256 is not null)throw new ArgumentException("Evidence references need their exact received submission and card.");
            if(command.Kind==WorkflowExceptionKind.ApprovedWithExceptions&&(source is null||source.Outcomes.Length==0||!source.HasOriginals))throw new OrganizationConflict("Approved With Exceptions needs an actual received result and retained supporting original observations/telemetry/documentation. Use an evidence-free waiver instead of manufacturing a pilot contribution.");
            var scope=Hash(new{program,command.PhaseId,command.OpportunityId,command.PublicationRevision,command.PublicationSha256,command.RequirementKey,command.Kind,command.RootReceiptId,command.LocalCardId});var newId=Guid.NewGuid();var member=await Active(actor,ct,true);
            if(command.SupersedesId is {} oldId){var oldRow=await db.WorkflowExceptions.SingleOrDefaultAsync(e=>e.Id==oldId&&e.ProgramId==program,ct)??throw new OrganizationNotFound();var old=await Exception(oldRow,ct);if(!old.Active||old.Revision!=command.ExpectedSupersededRevision||old.Definition.OpportunityId!=published.Id||old.Definition.RequirementKey!=command.RequirementKey||old.Definition.PhaseId!=command.PhaseId)throw new OrganizationConflict("The earlier disposition changed or belongs to a different purpose. Review the exact decision before superseding it.");await SaveException(oldRow,old with{Revision=old.Revision+1,Active=false,ActorId=id,Actor=name,ActorRole=member.Role,TimestampUtc=OrganizationTime.UtcNow,Action="superseded",SupersededBy=newId},ct);}
            else if(command.ExpectedSupersededRevision is not null)throw new ArgumentException("Choose the exact earlier disposition being superseded.");
            if(await db.WorkflowExceptions.AnyAsync(e=>e.Active&&e.ScopeSha256==scope,ct))throw new OrganizationConflict("An active disposition already exists for this exact purpose/source. Explicitly supersede or revoke it instead of creating a duplicate.");
            var value=new WorkflowExceptionSnapshot(1,newId,program,published.CampaignId,1,policy.RulesRevision,command,true,id,name,member.Role,OrganizationTime.UtcNow,"authorized",null,source?.Revision,source?.Head,source?.PilotId,source?.ClaimId,source?.Outcomes??[],source?.Signature??"",source?.State,source?.EvidenceSha256??Hash(Array.Empty<object>()),scope,published.Name,phase?.DefinitionRevision);var next=new WorkflowExceptionRecord{Id=newId};db.WorkflowExceptions.Add(next);await SaveException(next,value,ct);await Reconcile(program,ct);return value;
        },ct,async()=>{await Lock(ct);await Active(actor,ct,true);});
    }
    public Task<WorkflowExceptionSnapshot> RevokeException(Guid id,ExceptionRevokeCommand command,ClaimsPrincipal actor,CancellationToken ct)
    {
        if(command.Version!=1||command.RequestId==Guid.Empty||command.ExpectedRevision<1)throw new ArgumentException("Use the saved disposition revision and a new command identity.");ProgramWorkflowRules.Text(command.Reason,2000,"Revocation explanation");
        return history.Mutate(actor,command.RequestId,new{operation="revoke-workflow-exception",id,command},async(user,name)=>{var row=await db.WorkflowExceptions.SingleOrDefaultAsync(e=>e.Id==id,ct)??throw new OrganizationNotFound();var old=await Exception(row,ct);if(old.Revision!=command.ExpectedRevision||!old.Active)throw new OrganizationConflict("This disposition changed or was already revoked/superseded. Reload before deciding.");var member=await Active(actor,ct,true);var value=old with{Revision=old.Revision+1,Active=false,ActorId=user,Actor=name,ActorRole=member.Role,TimestampUtc=OrganizationTime.UtcNow,Action="revoked",Definition=old.Definition with{Reason=command.Reason.Trim()}};await SaveException(row,value,ct);await Reconcile(row.ProgramId,ct);return value;},ct,async()=>{await Lock(ct);await Active(actor,ct,true);});
    }
    public Task<OrganizationPage<WorkflowExceptionView>> Exceptions(Guid program,Guid? campaign,Guid? opportunity,int? publication,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? pilot=null)=>Snapshot(actor,pilot,async(user,manage)=>{
        if(offset<0||publication is <=0||publication is not null&&opportunity is null)throw new ArgumentException("Choose an exact published card and a valid disposition page.");_=await Program(program,ct);var policy=await Policy(program,ct);var q=db.WorkflowExceptions.AsNoTracking().Where(e=>e.ProgramId==program);if(campaign is {} c)q=q.Where(e=>e.CampaignId==c);if(opportunity is {} o)q=q.Where(e=>e.OpportunityId==o);if(publication is {} r)q=q.Where(e=>e.PublicationRevision==r);var rows=await q.OrderByDescending(e=>e.TimestampUtc).ThenBy(e=>e.Id).Skip(offset).Take(21).ToArrayAsync(ct);var result=new List<WorkflowExceptionView>();foreach(var row in rows.Take(20)){
            var original=await Exception(row,ct);var effective=original.Active&&original.RulesRevision==policy.RulesRevision;if(row.PhaseId is {} p){var phase=await db.TestPhases.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==p&&x.Enabled,ct);effective&=phase is not null&&phase.DefinitionRevision==row.PhaseDefinitionRevision;}
            if(effective)effective=await Effective(program,policy,row.PhaseId,row.PhaseDefinitionRevision).AnyAsync(e=>e.Id==row.Id,ct);var contributor=original.PilotId is {} id?"Contributor "+Hash(new{OrganizationId=(await members.Public(ct)).Id,PilotId=id})[..12]:"No pilot contribution — waiver only";var d=original.Definition;result.Add(new(row.Id,row.Revision,program,row.CampaignId,row.OpportunityId,row.PublicationRevision,row.PublicationSha256,original.CardName,d.RequirementKey,d.PhaseId,row.PhaseDefinitionRevision,d.Kind,original.Active,effective,!original.Active?original.Action:effective?"Authorized for the exact stated purpose — not scientific approval":"Not effective — policy, phase or same-card review changed; explicit reauthorization required",d.Reason,d.Justification,d.UnmetCriteria,d.CountAsPartialContributor,contributor,original.PilotId==user,original.OriginalOutcomes,original.Actor,original.ActorRole,original.TimestampUtc,original.Action,original.SupersededBy,manage?original:null,d.RequirementKey is {} key?Requirements(await Card(row.OpportunityId,row.PublicationRevision,ct)).Single(q=>q.Key==key).Name:"Entire published card"));}
        return new OrganizationPage<WorkflowExceptionView>(1,result.ToArray(),rows.Length>20?checked(offset+20):null);
    },ct);
    public Task<OrganizationPage<WorkflowSourceChoice>> Sources(Guid program,Guid opportunity,int publication,int offset,ClaimsPrincipal actor,CancellationToken ct)=>Snapshot(actor,null,async(_,manage)=>{
        if(!manage)throw new OrganizationForbidden();if(offset<0)throw new ArgumentException("Choose a valid received-source page.");var card=await Card(opportunity,publication,ct);if(card.ProgramId!=program)throw new OrganizationNotFound();var rows=await Live().Where(c=>c.OpportunityId==opportunity&&c.PublicationRevision==publication&&c.PublicationSha256==Hash(card)).OrderByDescending(c=>c.UpdatedUtc).ThenBy(c=>c.RootId).Skip(offset).Take(21).Join(db.Reviews,c=>c.RootId,r=>r.Id,(c,r)=>new WorkflowSourceChoice(c.RootId,c.CardId,r.Title,r.PilotName,c.State,r.Revision,c.ClaimId)).ToArrayAsync(ct);return new OrganizationPage<WorkflowSourceChoice>(1,rows.Take(20).ToArray(),rows.Length>20?checked(offset+20):null);
    },ct);
    public Task<OrganizationPage<WorkflowHistoryView>> History(Guid id,int offset,ClaimsPrincipal actor,CancellationToken ct,Guid? pilot=null)=>Snapshot(actor,pilot,async(_,_)=>{
        if(offset<0)throw new ArgumentException("Choose a valid history page.");var phase=await db.TestPhases.AsNoTracking().AnyAsync(p=>p.Id==id,ct);var exception=await db.WorkflowExceptions.AsNoTracking().AnyAsync(e=>e.Id==id,ct);var policy=await db.WorkflowPolicies.AsNoTracking().AnyAsync(p=>p.Id==id,ct);if(!phase&&!exception&&!policy)throw new OrganizationNotFound();var kind=phase?"test-phase":exception?"workflow-exception":"workflow-policy";var rows=await db.Revisions.AsNoTracking().Where(r=>r.ResourceId==id&&r.Kind==kind).OrderByDescending(r=>r.Revision).Skip(offset).Take(21).ToArrayAsync(ct);var result=new List<WorkflowHistoryView>();foreach(var row in rows.Take(20)){_=await history.ReadRevision(id,row.Revision,ct);if(phase){var p=Read<TestPhaseSnapshot>(row.SnapshotJson);result.Add(new(id,row.Revision,kind,p.Action,p.Reason,p.Actor,p.ActorRole,p.TimestampUtc,row.Sha256));}else if(exception){var p=Read<WorkflowExceptionSnapshot>(row.SnapshotJson);result.Add(new(id,row.Revision,kind,p.Action,p.Definition.Reason,p.Actor,p.ActorRole,p.TimestampUtc,row.Sha256));}else{var p=Read<ProgramPolicyView>(row.SnapshotJson);result.Add(new(id,row.Revision,kind,"policy-saved",p.Reason,p.Actor,p.ActorRole,p.TimestampUtc,row.Sha256));}}return new OrganizationPage<WorkflowHistoryView>(1,result.ToArray(),rows.Length>20?checked(offset+20):null);
    },ct);
